import type { Img } from "@/lib/types";
import data from "./photos.generated.json";

/**
 * Photo library. Everything is generated by `npm run photos` from source/photos using
 * scripts/photo-manifest.mjs (alt text, place, SEO file names). Do not edit photos.generated.json by hand.
 */
export interface Photo {
  id: number;
  place: string;
  alt: string;
  name: string;
  file: string;
  width: number;
  height: number;
  hero: boolean;
  og: string | null;
}
export interface Place { name: string; dest: string | null; blurb: string }

export const photos = data.photos as Photo[];
export const places = data.places as Record<string, Place>;

const byId = new Map(photos.map((p) => [p.id, p]));
const byFile = new Map(photos.map((p) => [p.file, p]));

export const toImg = (p: Photo, focal = "50% 50%"): Img => ({ src: p.file, alt: p.alt, focal, width: p.width, height: p.height });

const hero = (id: number, focal?: string): Img => {
  const p = byId.get(id);
  if (!p) throw new Error(`photo ${id} is not in the manifest`);
  return toImg(p, focal);
};

