export const photosByPlace = (place: string) => photos.filter((p) => p.place === place);
export const placeCover = (place: string) => (photosByPlace(place).find((p) => p.hero) ?? photosByPlace(place)[0])!;
export const placeForDestination = (dest: string) => Object.entries(places).find(([, v]) => v.dest === dest)?.[0] ?? null;

/** 1200x630 social image for a page image (falls back to the site default). */
export const socialImage = (src?: string) => {
  const p = src ? byFile.get(src) : undefined;
  return p?.og ? { url: p.og, alt: p.alt } : { url: "/og-default.jpg", alt: "Tailored Luxury Tours: private, tailor-made travel in Morocco" };
};
